def binary_search(L, target):
  beginning = 0
  end = len(L)
  while beginning < end:
    mid = (beginning + end)//2
    if L[mid] == target:
      return True
    elif L[mid] > target :
      end = mid
    else:
      beginning = mid + 1
  return False

